import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function readExplorerFile(e){return readFileSync(resolve(__dirname,"../../lala-lajpat-rai-explorer",e),"utf-8")}function readHubData(){return readFileSync(resolve(__dirname,"../../freedom-fighters-hub/script.js"),"utf-8")}describe("Lala Lajpat Rai Explorer — Page Structure",()=>{let e;beforeAll(()=>{e=readExplorerFile("index.html")}),it("contains a hero section with page title and kicker",()=>{expect(e).toContain('class="lajpat-rai-hero"'),expect(e).toContain("<h1>"),expect(e).toContain("Lala Lajpat Rai"),expect(e).toContain("Punjab Kesari"),expect(e).toContain("Lal-Bal-Pal")}),it("contains all required content sections from the issue",()=>{["biography","timeline","simon-commission","legacy","gallery","references"].forEach(t=>{expect(e).toContain(`id="${t}"`),expect(e).toContain(`data-tab="${t}"`)})}),it("highlights the Simon Commission protest and Lahore lathi charge",()=>{expect(e).toContain("Simon Commission"),expect(e).toContain("Lahore"),expect(e).toContain("lathi"),expect(e).toContain("30 October"),expect(e).toContain("coffin of British rule")}),it("has a semantic heading hierarchy (single h1, multiple h2s)",()=>{const t=(e.match(/<h1[\s>]/g)||[]).length,a=(e.match(/<h2[\s>]/g)||[]).length;expect(t).toBe(1),expect(a).toBeGreaterThanOrEqual(6)}),it("uses HTTPS image sources with alt attributes",()=>{const t=e.match(/<img [^>]*>/g)||[];expect(t.length).toBeGreaterThanOrEqual(6),t.forEach(e=>{expect(e).toMatch(/src="https:\/\//),expect(e).toMatch(/alt="/),expect(e).not.toMatch(/src="http:\/\//)})}),it("links the shared stylesheet, page stylesheet, and script",()=>{expect(e).toContain('href="../../styles.css"'),expect(e).toContain('href="style.css"'),expect(e).toContain('src="script.js"')}),it("references authentic source documentation in References",()=>{expect(e).toContain("wikipedia.org"),expect(e).toContain("britannica.com"),expect(e).toContain("indianexpress.com")})}),describe("Lala Lajpat Rai Explorer — Assets",()=>{it("includes a non-empty stylesheet themed for the freedom struggle",()=>{const e=readExplorerFile("style.css");expect(e.length).toBeGreaterThan(1e3),expect(e).toContain("lajpat-rai-hero")}),it("includes a valid interactive script with required functions",()=>{const e=readExplorerFile("script.js");expect(e).toContain("activateTab"),expect(e).toContain("initTabNavigation"),expect(e).toContain("initThemeToggle"),expect(e).toContain("document.addEventListener('DOMContentLoaded'")})}),describe("Lala Lajpat Rai — Landing Page (Freedom Fighters Hub) Integration",()=>{it("is listed as a card on the Freedom Fighters Hub landing page",()=>{const e=readHubData();expect(e).toContain("lajpat-rai"),expect(e).toContain("Lala Lajpat Rai")}),it("includes the Lal-Bal-Pal era metadata and a dedicated explorer link",()=>{const e=readHubData();expect(e).toContain("Punjab Kesari"),expect(e).toContain("Early Nationalist"),expect(e).toContain("Simon Commission Protest"),expect(e).toContain("../lala-lajpat-rai-explorer/index.html")})});